import{U as e,W as t,nt as n,t as r}from"./chunks/framework.BPwQCpO3.js";var i=JSON.parse(`{"title":"Plugin Architecture","description":"","frontmatter":{"title":"Plugin Architecture"},"headers":[],"relativePath":"guide/plugins.md","filePath":"guide/plugins.md","lastUpdated":1793267756000}`),a={name:`guide/plugins.md`};function o(r,i,a,o,s,c){return n(),e(`div`,null,[...i[0]||=[t(`<h1 id="_4-plugin-architecture" tabindex="-1">4. Plugin Architecture <a class="header-anchor" href="#_4-plugin-architecture" aria-label="Permalink to “4. Plugin Architecture”">​</a></h1><h2 id="_4-1-plugin-responsibilities" tabindex="-1">4.1 Plugin responsibilities <a class="header-anchor" href="#_4-1-plugin-responsibilities" aria-label="Permalink to “4.1 Plugin responsibilities”">​</a></h2><p>Plugins encapsulate specific resources or capabilities; they do not implement an independent self-healing system of their own.</p><p>A plugin may provide:</p><ul><li>Resource Provider.</li><li>Probe Provider.</li><li>Diagnosis Provider.</li><li>Recovery Action Provider.</li><li>Verification Provider.</li><li>Notification Channel Provider.</li></ul><p>One plugin may provide multiple capabilities.</p><p>For example, the OpenClash plugin could provide:</p><ul><li>The OpenClash service resource.</li><li>Proxy port probing.</li><li>Proxy authentication verification.</li><li>Node state diagnosis.</li><li>Node switching actions.</li><li>Service restart actions.</li><li>Node recovery verification.</li></ul><p>The Core Engine decides when these capabilities are invoked and whether execution is allowed.</p><h2 id="_4-2-plugin-execution-model" tabindex="-1">4.2 Plugin execution model <a class="header-anchor" href="#_4-2-plugin-execution-model" aria-label="Permalink to “4.2 Plugin execution model”">​</a></h2><p>The first version uses:</p><p><strong>Rust Core + external executable plugins + JSON-RPC 2.0 over stdio.</strong></p><p>Advantages:</p><ul><li>A plugin crash does not directly crash the core process.</li><li>Plugins can be implemented in different languages.</li><li>No need to design a stable Rust dynamic library ABI right away.</li><li>The plugin protocol can be versioned independently.</li><li>Easier to isolate plugin lifecycles and enforce timeouts.</li></ul><p>But be clear about this: an external process does not automatically constitute a security sandbox. Plugins still require least privilege, controlled working directories, controlled environment variables and explicit operation authorization.</p><h2 id="_4-3-plugin-protocol" tabindex="-1">4.3 Plugin protocol <a class="header-anchor" href="#_4-3-plugin-protocol" aria-label="Permalink to “4.3 Plugin protocol”">​</a></h2><p>The first version needs at least:</p><div class="language-text" dir="ltr"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>initialize</span></span>
<span class="line"><span>describe_capabilities</span></span>
<span class="line"><span>probe</span></span>
<span class="line"><span>diagnose</span></span>
<span class="line"><span>list_recovery_actions</span></span>
<span class="line"><span>execute_recovery_action</span></span>
<span class="line"><span>verify</span></span>
<span class="line"><span>shutdown</span></span></code></pre></div><p>These are logical operation names; they should ultimately map to versioned JSON-RPC methods.</p><p>A request must carry:</p><ul><li>A JSON-RPC ID.</li><li>The protocol version.</li><li>The method name.</li><li>Parameters.</li><li>A request timeout.</li><li>The associated Resource ID.</li><li>The associated RecoveryRun ID, when applicable.</li></ul><p>Recovery operations must use explicit action IDs with parameterized inputs. Piping arbitrary user input directly into Shell commands is forbidden.</p><h2 id="_4-4-engineering-requirements-for-stdio" tabindex="-1">4.4 Engineering requirements for stdio <a class="header-anchor" href="#_4-4-engineering-requirements-for-stdio" aria-label="Permalink to “4.4 Engineering requirements for stdio”">​</a></h2><p>On Windows, subprocess stdio pipes can block when their buffers fill up. The implementation must:</p><ul><li>Read stdout and stderr continuously and independently.</li><li>Use stdout only for protocol messages.</li><li>Use stderr for plugin diagnostic logs.</li><li>Limit single-message size.</li><li>Limit total buffer size.</li><li>Support chunked reading.</li><li>Handle incomplete messages.</li><li>Handle plugins exiting early.</li><li>Handle unresponsive plugins and timeouts.</li><li>Support request cancellation.</li><li>Return clear errors for malformed JSON and unknown methods.</li><li>Never parse stderr as a protocol response.</li></ul><p>For the first version, it is recommended to cap a single protocol message at 1 MiB, treat the exact value as a configurable safety limit, and handle large evidence via digest, truncation or chunking.</p><h2 id="_4-5-plugin-lifecycle" tabindex="-1">4.5 Plugin lifecycle <a class="header-anchor" href="#_4-5-plugin-lifecycle" aria-label="Permalink to “4.5 Plugin lifecycle”">​</a></h2><p>Long-lived plugin processes are recommended:</p><ol><li>Custos starts.</li><li>Configured plugins are started.</li><li>Protocol handshake completes.</li><li>Capability declarations are obtained.</li><li>Protocol compatibility is verified.</li><li>Requests are accepted.</li><li>Plugin health is monitored.</li><li>On plugin crash, restart according to policy.</li><li>If a plugin cannot be recovered, mark related resources as not effectively probeable or operable.</li><li>Record the plugin failure and notify.</li></ol><p>Plugins should not pay excessive overhead by re-creating a process for every probe.</p><h2 id="_4-6-capability-permissions" tabindex="-1">4.6 Capability permissions <a class="header-anchor" href="#_4-6-capability-permissions" aria-label="Permalink to “4.6 Capability permissions”">​</a></h2><p>Every capability should declare:</p><ul><li>Read-only or state-modifying.</li><li>Required permissions.</li><li>The scope of resources affected.</li><li>Whether it can interrupt the network.</li><li>Whether it can interrupt remote management.</li><li>Whether cancellation is supported.</li><li>Whether it is idempotent.</li><li>Whether verification is supported.</li><li>Possible failure states.</li><li>Whether compensation or rollback exists.</li></ul><p>The Core Engine decides whether to execute based on configuration and policy.</p><p>A plugin declaring an action does not automatically make it allowed.</p><hr><h2 id="plugin-model-ruling-user-decision-2026-10-29" tabindex="-1">Plugin model ruling (user decision, 2026-10-29) <a class="header-anchor" href="#plugin-model-ruling-user-decision-2026-10-29" aria-label="Permalink to “Plugin model ruling (user decision, 2026-10-29)”">​</a></h2><ul><li><strong>One plugin = the complete monitoring and handling logic for one resource type</strong>: probing, diagnosis, recovery actions and the verification loop live inside the same plugin, with no half-finished splits.</li><li><strong>Plugins can be depended on by other plugins</strong>: dependency direction matches the resource dependency graph, resolved uniformly by the Core Engine.</li><li><strong>Consumers enable a plugin with simple configuration only</strong>: declare the resource type and parameters, no glue code; configuration loading follows the configuration specification in §10.</li></ul><h2 id="builtin-capabilities-and-python-script-extension-user-decision-2026-10-29" tabindex="-1">Builtin capabilities and Python script extension (user decision, 2026-10-29) <a class="header-anchor" href="#builtin-capabilities-and-python-script-extension-user-decision-2026-10-29" aria-label="Permalink to “Builtin capabilities and Python script extension (user decision, 2026-10-29)”">​</a></h2><ul><li><strong>Builtin capabilities</strong>: the core engine ships built-in basic adapters for common resources (services, processes, disks, network connectivity, etc.) that work out of the box — basic scenarios require no plugin development at all.</li><li><strong>Python script extension (bidirectional)</strong>: <ul><li>Outbound: core functionality can be called from Python scripts via PyO3 bindings;</li><li>Inbound: custom probes and recovery actions can be written as Python scripts, loaded and executed by the core according to the plugin contract (timeouts, permissions and budgets follow the same rules as plugins).</li></ul></li></ul>`,40)]])}var s=r(a,[[`render`,o]]);export{i as __pageData,s as default};